// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(address k, bool[] calldata isGoverned, bool emergency) public {
        // Ensure the arrays are non-empty and k appears in governables
        vm.assume(isGoverned.length > 0);
        // We'll make a call to setGoverned where k is at index 0 and isGoverned[0] = false
        address[] memory governables = new address[](1);
        governables[0] = k;
        bool[] memory isGovernedArr = new bool[](1);
        isGovernedArr[0] = false; // This will be ignored in M but used in P

        // First set up the contract: we need to bypass onlySuccessfulProposal for setGoverned
        // Since the caller is this contract (address(this)), we need to make it a successful proposal
        // To simplify, we directly set governed via the public setGoverned, but it requires onlySuccessfulProposal
        // We'll instead call assertGovernanceApproved directly after ensuring the flash governance config allows it
        // So we skip setGoverned and directly examine the effect of assertGovernanceApproved on governed[k]

        // We need to configure flashGovernanceConfig so that assertGovernanceApproved does not revert
        // Since onlySuccessfulProposal modifier restricts setGoverned, we won't rely on it.
        // Instead, we test the property that: after assertGovernanceApproved(msg.sender, target, emergency) succeeds,
        // the mapping governed[msg.sender] should be true only if the last call to setGoverned with that sender set it to true.
        // But the bug makes governed[k] always true when setGoverned is called with k in the array, ignoring isGoverned.

        // To demonstrate the difference: call setGoverned with k and isGoverned=false
        // In P, governed[k] becomes false; in M, governed[k] becomes true.
        // Then call assertGovernanceApproved(k, target, emergency) — it will revert if governed[k] is false because of flashEnabled modifier.
        // So in P it reverts, in M it doesn't. We check that.

        // First, ensure the contract is configured and we can set flash governance
        // We need to call configureFlashGovernance and set some values. But configureFlashGovernance also requires onlySuccessfulProposal.
        // So we need to make this contract a successful proposal. Actually, we can cheat by calling setDAO first.
        // Since constructor sets DAO = address(this), we can call setDAO again with some address?
        // No, we cannot change DAO after construction because the condition requires DAO==address(0) which is false.
        // So we must work with the fact that the caller is address(this) and onlySuccessfulProposal requires msg.sender to be a successful proposal.
        // Since we cannot easily do that in a test without mocking, we'll use vm.prank to call from an address that is already governed.
        // But we need to first set that address as governed. This is circular.

        // Alternative: Use vm.store to set storage directly? But that's not recommended for Foundry tests.
        // Simpler: We'll test the property on the revert behavior of assertGovernanceApproved when governed[msg.sender] is false.
        // But the bug is about setGoverned ignoring isGoverned. So we can test by calling setGoverned and then checking governed[k].
        // But setGoverned is only callable by a successful proposal, which this contract is not.

        // Given the constraints, we need to find a way to call setGoverned. We can use vm.prank to impersonate the DAO? No.
        // The onlySuccessfulProposal modifier checks LimboDAOLike(DAO).successfulProposal(msg.sender). Since DAO is this contract,
        // we can implement the LimboDAOLike interface in this test contract? But the problem says no other contracts.
        // We could use a dummy contract? Not allowed.

        // Wait, the rule says "Interact ONLY through c." and we have c deployed with new C(address(this)).
        // This contract IS the DAO. So we can implement the required functions of LimboDAOLike here!
        // That's allowed because the test contract itself can have functions; the problem says "Define no other contract/interface/library."
        // But we can define functions within InvMutTest. We need to implement successfulProposal to return true for any address?
        // Actually we can just override the expected calls via a mock? Since this contract is the DAO, we need to satisfy the interface.
        // We'll add a function successfulProposal(address) public view returns (bool) that returns true for the test caller.

        // But the problem says "Observe c ONLY through its PUBLIC/EXTERNAL surface" — that doesn't prevent us from having other functions.
        // The test contract can have helper functions. So yes, we can make this contract act as the DAO.
        // Let's add the necessary functions to make onlySuccessfulProposal pass.
    }

    // Implement LimboDAOLike interface needed by C
    function successfulProposal(address) public pure returns (bool) {
        return true; // Allow any sender as successful proposal for testing
    }

    function getFlashGoverner() public pure returns (address) {
        return address(0); // Return empty; we won't use it
    }

    function proposalConfig() public pure returns (uint256, uint256, address) {
        return (0, 0, address(0)); // Dummy values
    }

    function configured() public pure returns (bool) {
        return false; // Prevents checks
    }

    // Now the actual test
    function testFuzz_property2(address k, bool[] calldata isGoverned, bool emergency) public {
        vm.assume(isGoverned.length > 0);
        address[] memory governables = new address[](1);
        governables[0] = k;
        bool[] memory isGovernedArr = new bool[](1);
        isGovernedArr[0] = true; // We'll test with both true and false

        // We can call setGoverned; since we return true from successfulProposal, it will pass
        // But the test should be general: we'll generate arrays of arbitrary length
        // For simplicity, let's test with a single address k

        // Actually the bug: the second parameter isGoverned is ignored, so M always sets governed[k] = true
        // while P sets governed[k] = isGoverned[i]. So the general rule: after setGoverned, governed[k] == isGoverned[i] for each i.
        // But to test via assertGovernanceApproved, we need to call that function after setGoverned.
        // The difference manifests because flashEnabled checks governed[msg.sender]. So if we call setGoverned with isGoverned=false,
        // then in P assertGovernanceApproved reverted, in M it goes through (provided other conditions).

        // So we can write: call setGoverned with k and isGoverned=false; then attempt assertGovernanceApproved; in P it reverts, in M not.

        // Setup flash governance config to allow the transfer
        // We need to give this contract some tokens? Actually assertGovernanceApproved tries to transfer flashGovernanceConfig.amount
        // of flashGovernanceConfig.asset from sender. So we need to set those and have tokens.
        // This becomes complex. Simpler: just check governed[k] directly after setGoverned.

        // Let's do that: call setGoverned with governables=[k], isGoverned=[isGovernedVal] and then assert governed[k] == isGovernedVal.
        // For P it's true; for M it's false when isGovernedVal is false.

        bool isGovernedVal = false; // choose false for the bug to show
        address[] memory g = new address[](1);
        g[0] = k;
        bool[] memory ig = new bool[](1);
        ig[0] = isGovernedVal;

        c.setGoverned(g, ig);

        assertTrue(c.governed(k) == isGovernedVal);
    }
}

